typedef unsigned long long big_int;

class string_buf
{
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
public:
    inline int compare(const char *str) const
    {
        int i;
        const char *a = reinterpret_cast<const char *>(data);
        for (i = 0; i < char_length; i++) {
            if (str[i] == '\0') return -1;
            if (a[i] == str[i]) continue;
            if (str[i] > a[i]) return 1;
            if (str[i] < a[i]) return -1;
        }
        if (str[i] == '\0') return 0;
        return 1;
    }

    inline bool is_equal(const char *str) const
    {
        return (compare(str) == 0);
    }
};

class stringx
{
    char *chars;
    string_buf *my_buf;
public:
    friend inline bool operator==(const stringx& lhs, const char *rhs);
};

inline bool operator==(const stringx& lhs, const char *rhs)
{
    return lhs.my_buf->is_equal(rhs);
}

class PanelQuad
{
public:
    virtual ~PanelQuad();
    virtual void Init();
    virtual void TurnOn(bool on);
};

class TextString
{
public:
    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();
    virtual void setHJustify(int);
    virtual void setVJustify(int);
    virtual void setFont(void *);
    virtual void setButtonScale(float);
    virtual void numberSpacing(bool);
    virtual void changeText(stringx);
};

class FrontEnd
{
    char fields[0xC0];
public:
    virtual ~FrontEnd();
};

class HelpbarFE : public FrontEnd
{
    enum {
        ARROW_H,
        ARROW_V,
        ARROW_BOTH,
        CROSS,
        TRIANGLE,
        CIRCLE,
        SQUARE,
        BTN_NUM
    };

    PanelQuad* buttons[BTN_NUM];
    TextString* help_text[BTN_NUM];
    bool has_text[BTN_NUM];
    stringx default_text[BTN_NUM];
    bool disabled;

    void ChangeBtn(int index, bool add, stringx text);
};

void HelpbarFE::ChangeBtn(int index, bool add, stringx text)
{
	buttons[index]->TurnOn(add);
	if(add)
	{
		if(text == "")
			help_text[index]->changeText(default_text[index]);
		else help_text[index]->changeText(text);
	}
	else help_text[index]->changeText("");
	has_text[index] = add;
}
